main.gd._production_worker_station_position:
func _production_worker_station_position(station_name: String) -> Vector3:
	var action_target:Variant=preload("res://scripts/production_actions.gd").target(self,production_worker_pending_action,production_worker_pending_slot)
	if action_target is Vector3 and station_name in ["workbench","grow"]:return action_target
	if inventory_system!=null and inventory_system.furniture!=null and inventory_system.worker_property()=="house":
		var model:RefCounted=inventory_system.furniture.model
		if station_name=="entry":return Vector3(35.0,0.0,1.45)
		if station_name=="idle":
			if neighborhood!=null and neighborhood.location_ops!=null and neighborhood.location_ops.crew!=null:return neighborhood.location_ops.crew.idle_spot(false,false,"house")
			return Vector3(31.5,0.0,-2.4)
		var kind:String={"workbench":"packing","storage":"storage","grow":"tent"}.get(station_name,"")
		if station_name=="grow":
			var selected_id:String=model.item_for_slot(production_worker_pending_slot)
			if not selected_id.is_empty():
				var selected:Dictionary=model.state.items[selected_id]
				if selected.get("property","")=="house" and selected.has("position"):
					return Vector3(float(selected.position[0])-1.2,float(selected.position[1]),float(selected.position[2]))
			for id in model.state.items:
				var entry:Dictionary=model.state.items[id]
				if entry.get("property","")=="house" and str(entry.get("sku","")).begins_with("tent_") and entry.has("position"):
					return Vector3(float(entry.position[0])-1.2,float(entry.position[1]),float(entry.position[2]))
			return Vector3(40.4,0.0,-9.0)
		if not kind.is_empty():
			var station_id:String=model.primary("house",kind)
			if not station_id.is_empty():
				var e:Dictionary=model.state.items[station_id]
				if e.has("position"):return Vector3(float(e.position[0])-1.3,float(e.position[1]),float(e.position[2]))
		return Vector3(28.5,0.0,-0.8)
	match station_name:
		"grow": return Vector3(0.70, 0.0, -6.45)
		"workbench": return Vector3(2.85, 0.0, 0.30)
		"storage": return Vector3(-3.25, 0.0, -0.15) # Clear the vault handle and worker radius.
		"entry": return Vector3(0.65, 0.0, 3.85)
		_:
			if neighborhood != null and neighborhood.location_ops != null and neighborhood.location_ops.crew != null:
				return neighborhood.location_ops.crew.idle_spot(false,false)
			return Vector3(-0.75, 0.0, 1.25)

main.gd._reset_production_worker_navigation:
func _reset_production_worker_navigation() -> void:
	if house_npc_navigation!=null:house_npc_navigation.reset("production")
	production_worker_route_points.clear()
	production_worker_route_index = 0
	production_worker_route_valid = false
	production_worker_stall_seconds = 0.0

main.gd._production_worker_navigation_target:
func _production_worker_navigation_target() -> Vector3:
	# House workers navigate to the house stations, not old apartment hallway waypoints.
	if inventory_system!=null and inventory_system.worker_property()=="house":
		return _house_worker_navigation_target()
	if production_worker_node == null:
		return production_worker_target_position
	var worker_pos: Vector3 = production_worker_node.position
	var target: Vector3 = production_worker_target_position
	if not production_worker_route_valid or production_worker_route_destination.distance_to(target) > 0.01:
		production_worker_route_points.clear()
		production_worker_route_index = 0
		production_worker_route_destination = target
		production_worker_route_valid = true
		var main_side: Vector3 = Vector3(0.0, 0.0, -3.15)
		var grow_side: Vector3 = Vector3(0.0, 0.0, -5.05)
		if target.z < -4.30 and worker_pos.z > -4.30:
			if worker_pos.z > main_side.z:
				production_worker_route_points.append(main_side)
			production_worker_route_points.append(grow_side)
		elif target.z > -3.70 and worker_pos.z < -3.70:
			if worker_pos.z < grow_side.z:
				production_worker_route_points.append(grow_side)
			production_worker_route_points.append(main_side)
		production_worker_route_points.append(target)
	while production_worker_route_index < production_worker_route_points.size():
		var waypoint: Vector3 = production_worker_route_points[production_worker_route_index]
		if worker_pos.distance_to(waypoint) > 0.08:
			return waypoint
		production_worker_route_index += 1
	return target

main.gd._update_production_worker_visual:
func _update_production_worker_visual(delta: float) -> void:
	if _simulation_blocked():
		return
	if production_worker_node == null:
		return
	var on_duty: bool = packing_employee_hired and packing_employee_active and (neighborhood==null or neighborhood.location_ops.crew.shop.production_allowed())
	production_worker_node.visible = packing_employee_hired and not production_worker_arrested
	if not on_duty:
		if production_worker_node.visible and not bool(production_worker_node.get_meta("seated",false)):
			production_worker_target_position=_production_worker_station_position("idle")
			production_worker_node.position=production_worker_node.position.move_toward(_production_worker_navigation_target(),PRODUCTION_WORKER_MOVE_SPEED*delta)
		return
	var worker_idle: bool=production_worker_pending_action.is_empty() and (production_worker_task=="Waiting for work" or lay_low_active)
	if worker_idle:
		production_worker_target_position=_production_worker_station_position("idle")
		if bool(production_worker_node.get_meta("seated",false)):
			return
	var move_target: Vector3 = _production_worker_navigation_target()
	var before: Vector3 = production_worker_node.position
	production_worker_node.position = before.move_toward(move_target, PRODUCTION_WORKER_MOVE_SPEED * delta)
	var movement: Vector3 = production_worker_node.position - before
	var remaining_before: float = before.distance_to(move_target)
	var remaining_after: float = production_worker_node.position.distance_to(move_target)
	if remaining_before > 0.08 and remaining_before - remaining_after <= 0.000001:
		production_worker_stall_seconds += delta
	else:
		production_worker_stall_seconds = 0.0
	if production_worker_stall_seconds > 0.75:
		_reset_production_worker_navigation()
	var moving: bool = movement.length() > 0.002
	if moving:
		production_worker_node.rotation.y = lerp_angle(production_worker_node.rotation.y, atan2(-movement.x, -movement.z), minf(1.0, delta * 8.0))
		production_worker_walk_phase += movement.length() * 4.5
	else:
		production_worker_walk_phase = lerpf(production_worker_walk_phase, 0.0, minf(1.0, delta * 5.0))
	var walk_swing: float = sin(production_worker_walk_phase) * 0.42 if moving else 0.0
	var arm_l: MeshInstance3D = production_worker_node.get_node_or_null("ArmL") as MeshInstance3D
	var arm_r: MeshInstance3D = production_worker_node.get_node_or_null("ArmR") as MeshInstance3D
	var leg_l: MeshInstance3D = production_worker_node.get_node_or_null("LegL") as MeshInstance3D
	var leg_r: MeshInstance3D = production_worker_node.get_node_or_null("LegR") as MeshInstance3D
	if arm_l != null:
		arm_l.rotation.x = lerpf(arm_l.rotation.x, walk_swing, minf(1.0, delta * 12.0))
	if arm_r != null:
		arm_r.rotation.x = lerpf(arm_r.rotation.x, -walk_swing, minf(1.0, delta * 12.0))
	if leg_l != null:
		leg_l.rotation.x = lerpf(leg_l.rotation.x, -walk_swing * 0.75, minf(1.0, delta * 12.0))
	if leg_r != null:
		leg_r.rotation.x = lerpf(leg_r.rotation.x, walk_swing * 0.75, minf(1.0, delta * 12.0))
	if production_worker_task_label != null:
		var worker_name: String = production_worker_friend_name if not production_worker_friend_name.is_empty() else "PRODUCTION WORKER"
		production_worker_task_label.text = "%s  |  %s" % [worker_name.to_upper(), production_worker_task.to_upper()]
	_refresh_production_worker_friend_face()

	if production_worker_pending_action.is_empty():
		production_worker_action_dwell = 0.0
		return
	var at_station:bool=house_route_arrived("production",production_worker_node.position,production_worker_target_position) if inventory_system!=null and inventory_system.worker_property()=="house" else production_worker_node.position.distance_to(production_worker_target_position)<=0.16
	if not at_station:
		production_worker_action_dwell = 0.0
		return
	production_worker_action_dwell += delta
	if production_worker_action_dwell >= preload("res://scripts/production_actions.gd").duration(production_worker_pending_action):
		var finished_action:String=production_worker_pending_action
		production_worker_action_dwell = 0.0
		_execute_production_worker_action()
		if finished_action=="trim":_assign_production_worker_task()

main.gd._house_worker_navigation_target:
func _house_worker_navigation_target()->Vector3:
	if production_worker_node==null:return production_worker_target_position
	var waypoint:Vector3=house_route_next("production",production_worker_node.position,production_worker_target_position)
	# Mirror the route for existing map QA and in-game path debugging.
	var record:Dictionary=_house_npc_route().routes.get("production",{})
	production_worker_route_points.clear()
	for point in record.get("points",[]):production_worker_route_points.append(point)
	production_worker_route_index=int(record.get("index",0))
	production_worker_route_valid=not production_worker_route_points.is_empty()
	return waypoint

crew_phone.gd.update:
func update(delta: float) -> void:
	if not host.customer_waiting:manager_attempted=false
	update_malik()
	update_seating(delta)
	if bool(host.location_state.get("crew_idle",false)) and not host.lay_low_active:host.location_state["crew_idle"]=false
	var active_site:String=ops.active_property()
	var name:=manager(active_site) if active_site in ["apartment","house"] else ""
	if manager_node!=null and (str(manager_node.get_meta("contact",""))!=name or str(manager_node.get_meta("property","apartment"))!=active_site):manager_node.queue_free();manager_node=null
	if not name.is_empty() and host.production_worker_node!=null:
		if manager_node==null:
			manager_node=character_instance(name) if FriendCharacters.has_character(name) else generic_manager_instance(name)
			manager_node.name="PropertyDoorManager";host.add_child(manager_node);manager_node.set_meta("contact",name)
			if active_site=="house":manager_node.position=Vector3(35,0,1.45)
			manager_node.set_meta("property",active_site)
			for tag in manager_node.find_children("*","Label3D",true,false):tag.text=name+(" · DOOR DEALER" if role(name)=="door" else " · APARTMENT DEALER")
		manager_node.visible=not host.dealer_arrested or role(name)=="door"
		var couch: Dictionary=idle_couch(active_site)
		var relax: bool=not couch.is_empty() and not host.customer_waiting and not world.couch_seated
		var seat: Vector3=idle_spot(true,false,active_site)
		var before: Vector3=manager_node.position
		var already_seated: bool=bool(manager_node.get_meta("seated",false))
		var previous_seat: Vector3=manager_node.get_meta("idle_seat_position",Vector3.ZERO)
		var same_seat: bool=already_seated and str(manager_node.get_meta("idle_seat_id",""))==str(couch.get("id","")) and previous_seat.distance_to(seat)<0.03
		var seated: bool=relax and same_seat
		if not seated:
			# Movement is horizontal. Never chase the zero-height navigation
			# target after the sitting pose lowers a character's visual root.
			manager_node.position.y=0.0
			var door_position:Vector3=Vector3(35,0,2.1) if active_site=="house" else Vector3(1.45,0,4.45)
			var destination: Vector3=seat if relax else (door_position if host.customer_waiting else idle_spot(true,true,active_site))
			var waypoint:Vector3=host.house_route_next("door_"+name,manager_node.position,destination) if active_site=="house" else destination
			manager_node.position=manager_node.position.move_toward(waypoint,delta*2.0)
			var arrived:bool=(host.house_route_arrived("door_"+name,manager_node.position,destination) and manager_node.position.distance_to(seat)<1.1) if active_site=="house" else Vector2(manager_node.position.x-seat.x,manager_node.position.z-seat.z).length()<0.12
			seated=relax and arrived and (not already_seated or same_seat)
		if seated:
			manager_node.position.x=seat.x
			manager_node.position.z=seat.z
			manager_node.rotation.y=float(couch.get("yaw",0.0))
			manager_node.set_meta("idle_seat_id",str(couch.get("id","")))
			manager_node.set_meta("idle_seat_position",seat)
		else:
			manager_node.set_meta("idle_seat_id","")
		seated_pose(manager_node,seated)
		animate_manager(Vector3(manager_node.position.x-before.x,0,manager_node.position.z-before.z),seated,delta)
		var visit_target:Vector3=Vector3(35,0,2.1) if active_site=="house" else Vector3(1.45,0,4.45)
		var at_door:bool=host.house_route_arrived("door_"+name,manager_node.position,visit_target) if active_site=="house" else manager_node.position.distance_to(visit_target)<0.2
		if host.customer_waiting and not host.customer_answered and not host.customer_departing and can_handle(active_site) and not manager_attempted and at_door and str(host.current_customer.get("special","")).is_empty():
			manager_attempted=true
			var client: Dictionary=host.current_customer.duplicate(true)
			var request: Dictionary=host.active_request.duplicate(true)
			if not serve_visit(client,request):
				send(name,say(name,"short_stock",{"client":str(client.get("name","client")),"qty":int(request.get("qty",0)),"product":str(request.get("product",""))}))
				if not world.client_visits.is_home():world.client_visits._release_visit();world.client_visits._send_missed(client,request,"Your dealer could not fill my order. Let me know when you have stock.")
	elif manager_node!=null:manager_node.hide()
	tick+=delta
	if tick<10 or host._simulation_blocked():return
	tick=0
	if host.business_open and host.dealers_active and host._total_dealer_count()>0:alert(name if not name.is_empty() else host._critical_dealer_sender(),"dealer_stock",packaged_stock()==0 if not name.is_empty() else property_supply_empty(assignment(host._critical_dealer_sender()),"product|", "dealer"),"Apartment packaged stock is empty. Restock it so I can serve the door." if not name.is_empty() else "Dealer Locker is empty. I cannot sell on the street until you restock it.")
	if host.packing_employee_hired and host.packing_employee_active:
		var worker: String=host._critical_production_sender()
		alert(worker,"seeds",property_supply_empty(assignment(worker),"seed|"),"We're out of seeds. Collect an order at Central Market and deposit it at the computer.")
		alert(worker,"fertilizer",property_supply_empty(assignment(worker),"fertilizer"),"Fertilizer is out. I'll keep watering existing plants, but you'll need to restock fertilizer at Central Market.")

crew_phone.gd.idle_couch:
func idle_couch(property_id:String="apartment") -> Dictionary:
	if host.inventory_system == null or host.inventory_system.furniture == null:return {}
	var model: RefCounted=host.inventory_system.furniture.model
	var candidate: Dictionary={}
	for id in model.state.items:
		var e: Dictionary=model.state.items[id]
		if e.get("sku","")!="sofa" or e.get("property","")!=property_id or not e.has("position"):continue
		var p: Array=e.position
		candidate={"id":id,"origin":Vector3(float(p[0]),0.0,float(p[2])),"yaw":deg_to_rad(float(e.get("yaw",0.0)))}
		if str(id)=="legacy_sofa":break
	if candidate.is_empty() and property_id=="house":return {"id":"house_fitted_couch","origin":Vector3(29.2,0,-3.6),"yaw":PI}
	return candidate

crew_phone.gd.idle_spot:
func idle_spot(manager: bool=false,approach: bool=false,property_id:String="apartment") -> Vector3:
	var couch: Dictionary=idle_couch(property_id)
	if couch.is_empty():
		# No apartment couch means crew stay standing in a clear idle area.
		return Vector3(35.0 if manager else 34.3,0.0,1.45) if property_id=="house" else Vector3(0.75 if manager else -0.75,0.0,1.25)
	var second: bool=manager and host.packing_employee_hired
	var offset: Vector3=Vector3(0.615 if second else -0.375,0.0,-1.10 if approach else -0.165)
	return (couch["origin"] as Vector3)+offset.rotated(Vector3.UP,float(couch["yaw"]))

crew_phone.gd.update_seating:
func update_seating(_delta: float) -> void:
	var worker: Node3D=host.production_worker_node
	if worker!=null and worker.visible:
		var idle: bool=host.production_worker_pending_action.is_empty() and (not host.packing_employee_active or host.production_worker_task=="Waiting for work" or host.lay_low_active)
		var property_id:String=host.inventory_system.worker_property() if host.inventory_system!=null else "apartment"
		var couch: Dictionary=idle_couch(property_id)
		var seat: Vector3=idle_spot(false,false,property_id)
		var already_seated: bool=bool(worker.get_meta("seated",false))
		var previous_seat: Vector3=worker.get_meta("idle_seat_position",Vector3.ZERO)
		var same_seat: bool=already_seated and str(worker.get_meta("idle_seat_id",""))==str(couch.get("id","")) and previous_seat.distance_to(seat)<0.03
		var arrived: bool=(host.house_route_arrived("production",worker.position,seat) and worker.position.distance_to(seat)<1.1) if property_id=="house" else Vector2(worker.position.x-seat.x,worker.position.z-seat.z).length()<0.15
		var seated: bool=idle and not couch.is_empty() and not world.couch_seated and arrived and (not already_seated or same_seat)
		if seated:
			# Hold the cushion position. Navigation must not pull us back
			# toward the table/front-of-couch approach point.
			worker.position.x=seat.x
			worker.position.z=seat.z
			worker.rotation.y=float(couch.get("yaw",0.0))
			worker.set_meta("idle_seat_id",str(couch.get("id","")))
			worker.set_meta("idle_seat_position",seat)
		else:
			worker.set_meta("idle_seat_id","")
		worker.set_meta("seated",seated)
		if malik_worker!=null:seated_pose(malik_worker,seated)
		else:
			for part in ["LegL","LegR"]:
				var leg: Node3D=worker.get_node_or_null(part)
				if leg!=null:leg.rotation.x=-PI/2 if seated else 0.0
			worker.position.y=-0.57 if seated else 0.0

main.gd._house_npc_route:
func _house_npc_route() -> RefCounted:
	if house_npc_navigation==null:
		house_npc_navigation=preload("res://scripts/house_npc_navigation.gd").new()
		house_npc_navigation.setup(self)
	return house_npc_navigation
